import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    color = [-1] * (n + 1)
    has_odd_cycle = False
    bipartite_components = []
    non_bipartite_count = 0

    for start in range(1, n + 1):
        if visited[start]:
            continue

        component_nodes = []
        q = deque([start])
        visited[start] = True
        color[start] = 0
        component_nodes.append(start)
        is_bipartite = True

        while q:
            u = q.popleft()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    color[v] = color[u] ^ 1
                    component_nodes.append(v)
                    q.append(v)
                else:
                    if color[v] == color[u]:
                        is_bipartite = False

        if is_bipartite:
            c0 = sum(1 for x in component_nodes if color[x] == 0)
            c1 = len(component_nodes) - c0
            bipartite_components.append((c0, c1))
        else:
            non_bipartite_count += 1

    if non_bipartite_count > 0:
        print(f"0 1")
        return

    if len(bipartite_components) == 0:
        pass
    elif len(bipartite_components) == 1:
        c0, c1 = bipartite_components[0]
        if c0 * c1 == n * (n - 1) // 2:
            if n < 3:
                print(f"3 1")
            else:
                total_possible = n * (n - 1) // 2
                existing = m
                missing = total_possible - existing
                if missing == 0:
                    if n >= 3:
                        print(f"1 {missing}")
                    else:
                        print(f"3 1")
                else:
                    if missing > 0:
                        print(f"1 {missing}")
                    else:
                         print(f"3 1")
        else:
            missing = c0 * c1 - m
            if missing > 0:
                print(f"1 {missing}")
            else:
                print(f"3 1")
    else:
        ways = 0
        total_vertices = 0
        for c0, c1 in bipartite_components:
            total_vertices += (c0 + c1)

        for i in range(len(bipartite_components)):
            c0_i, c1_i = bipartite_components[i]
            size_i = c0_i + c1_i
            others = total_vertices - size_i
            ways += c0_i * others + c1_i * others

        print(f"1 {ways}")

if __name__ == "__main__":
    main()
